/**
 * src/components/DevDashboard/index.jsx
 * ============================================================================
 * Dev-only dashboard: frontmatter schema coverage for docs/articles.
 * Fetches /build-report.json (generated by scripts/generate-build-report.mjs).
 */

import React, { useEffect, useState } from 'react';
import useBaseUrl from '@docusaurus/useBaseUrl';
import {
  PieChart,
  Pie,
  Cell,
  Tooltip,
  Legend,
  ResponsiveContainer,
  BarChart,
  Bar,
  XAxis,
  YAxis,
  CartesianGrid,
} from 'recharts';
import styles from './styles.module.css';

const COLORS = [
  '#6f2dbd', '#5a189a', '#b185db', '#7b2cbf', '#9d4edd',
  '#4a4e69', '#8f5ad6', '#3c096c', '#c77dff', '#240046',
];

function ProgressRow({ label, percent, presentCount, totalDocs, required }) {
  return (
    <div className={styles.progressRow}>
      <div className={styles.progressLabel}>
        {label}
        {required ? <span className={styles.requiredBadge}>required</span> : null}
        <span className={styles.progressCount}>
          {presentCount}/{totalDocs}
        </span>
      </div>
      <div className={styles.progressTrack}>
        <div
          className={styles.progressFill}
          style={{ width: `${percent}%` }}
        />
      </div>
    </div>
  );
}

function DonutCard({ field }) {
  return (
    <div className={styles.card}>
      <h3 className={styles.cardTitle}>{field.label}</h3>
      <ResponsiveContainer width="100%" height={260}>
        <PieChart>
          <Pie
            data={field.values}
            dataKey="count"
            nameKey="value"
            innerRadius={60}
            outerRadius={90}
            paddingAngle={2}
          >
            {field.values.map((entry, index) => (
              <Cell key={entry.value} fill={COLORS[index % COLORS.length]} />
            ))}
          </Pie>
          <Tooltip />
          <Legend />
        </PieChart>
      </ResponsiveContainer>
    </div>
  );
}

function BarCard({ field }) {
  const data = field.values.slice(0, 10);

  return (
    <div className={styles.card}>
      <h3 className={styles.cardTitle}>{field.label}</h3>
      <ResponsiveContainer width="100%" height={280}>
        <BarChart data={data} layout="vertical" margin={{ left: 20, right: 20 }}>
          <CartesianGrid strokeDasharray="3 3" />
          <XAxis type="number" allowDecimals={false} />
          <YAxis type="category" dataKey="value" width={130} tick={{ fontSize: 12 }} />
          <Tooltip />
          <Bar dataKey="count" fill="#6f2dbd" radius={[0, 4, 4, 0]} />
        </BarChart>
      </ResponsiveContainer>
    </div>
  );
}

export default function DevDashboard() {
  const reportUrl = useBaseUrl('/build-report.json');
  const [report, setReport] = useState(null);
  const [error, setError] = useState('');

  useEffect(() => {
    fetch(reportUrl)
      .then((res) => {
        if (!res.ok) {
          throw new Error(`HTTP ${res.status}`);
        }
        return res.json();
      })
      .then(setReport)
      .catch((err) => setError(err.message));
  }, [reportUrl]);

  if (error) {
    return (
      <div className={styles.message}>
        <h2>Could not load build-report.json</h2>
        <p>{error}</p>
        <p>
          Run <code>npm run build-report</code>, then restart the dev server.
        </p>
      </div>
    );
  }

  if (!report) {
    return <div className={styles.message}>Loading build report…</div>;
  }

  const progressFields = report.fields.filter((field) => field.chartType === 'progress');
  const donutFields = report.fields.filter((field) => field.chartType === 'donut' && field.values.length > 0);
  const barFields = report.fields.filter((field) => field.chartType === 'bar' && field.values.length > 0);
  const incompleteRequired = report.fields.filter(
    (field) => field.required && field.missing.length > 0,
  );
  const completePercent = report.totalDocs > 0
    ? Math.round((report.requiredComplete / report.totalDocs) * 100)
    : 0;

  return (
    <div className={styles.dashboard}>
      <header className={styles.header}>
        <h1>Dev Dashboard</h1>
        <p className={styles.subtitle}>
          Frontmatter schema coverage for docs/articles — generated{' '}
          {new Date(report.generatedAt).toLocaleString()}
        </p>
      </header>

      <section className={styles.statGrid}>
        <div className={styles.statCard}>
          <div className={styles.statValue}>{report.totalDocs}</div>
          <div className={styles.statLabel}>Documents scanned</div>
        </div>
        <div className={styles.statCard}>
          <div className={styles.statValue}>{report.requiredComplete}</div>
          <div className={styles.statLabel}>All required fields complete</div>
        </div>
        <div className={styles.statCard}>
          <div className={styles.statValue}>{completePercent}%</div>
          <div className={styles.statLabel}>Required completeness</div>
        </div>
      </section>

      <section className={styles.section}>
        <h2>Field Coverage</h2>
        <div className={styles.card}>
          {progressFields.map((field) => (
            <ProgressRow
              key={field.key}
              label={field.label}
              percent={field.percent}
              presentCount={field.presentCount}
              totalDocs={report.totalDocs}
              required={field.required}
            />
          ))}
        </div>
      </section>

      {donutFields.length > 0 && (
        <section className={styles.section}>
          <h2>Taxonomy Distribution</h2>
          <div className={styles.cardGrid}>
            {donutFields.map((field) => (
              <DonutCard key={field.key} field={field} />
            ))}
          </div>
        </section>
      )}

      {barFields.length > 0 && (
        <section className={styles.section}>
          <h2>Value Frequency</h2>
          <div className={styles.cardGrid}>
            {barFields.map((field) => (
              <BarCard key={field.key} field={field} />
            ))}
          </div>
        </section>
      )}

      <section className={styles.section}>
        <h2>Missing Required Fields</h2>
        {incompleteRequired.length === 0 ? (
          <p className={styles.allClear}>Every document has all required fields.</p>
        ) : (
          <div className={styles.card}>
            {incompleteRequired.map((field) => (
              <details key={field.key} className={styles.missingGroup}>
                <summary>
                  {field.label} — missing in {field.missing.length}{' '}
                  {field.missing.length === 1 ? 'doc' : 'docs'}
                </summary>
                <ul className={styles.missingList}>
                  {field.missing.map((file) => (
                    <li key={file}>
                      <code>{file}</code>
                    </li>
                  ))}
                </ul>
              </details>
            ))}
          </div>
        )}
      </section>
    </div>
  );
}
